$details=[
'core-site'=>['Overview'=>'Controls the public identity of PocketCat. The Website Name appears in public-facing branding and the Website URL is used as the canonical application URL.','Requirements'=>'Administrator access is required. Keep the URL consistent with the domain actually mapped to the PocketCat installation.','Steps'=>['Open the Site Settings screen.','Enter the public website name.','Enter the canonical HTTPS URL without a trailing slash.','Save Site Settings.','Open the Live Site Editor if you need visual changes.'],'Examples'=>'Website Name: <code>PocketCat</code><br>Website URL: <code>https://pocketcat.online</code>','Troubleshooting'=>['If redirects point to the wrong host, verify the Website URL and the hosting/domain mapping.','If a change appears cached, test in a private window and check the current public URL.'],'Official'=>[]],
'editor-suite'=>['Overview'=>'The Hybrid Editor Suite combines a conventional docked WYSIWYG/HTML editor with frontend in-context editing. Backend mode is suited to posts/pages; frontend mode lets an administrator edit the selected live element and publish without leaving the page.','Requirements'=>'Admin permissions, a valid CSRF token and the editor API. Frontend visual mode additionally requires an administrator with the visual-editor permission.','Steps'=>['Open the backend editor/site editor.','Use the Visual tab for rich editing or Code / HTML for source editing.','On the frontend, enable visual mode and click the pencil on an editable element.','Edit content or use the floating toolbar.','Review the live DOM result and choose Publish / Save Changes.','Use revisions or Revert to Original if needed.'],'Examples'=>'Visual tab: formatted content. Code tab: <code>&lt;strong&gt;Important&lt;/strong&gt;</code><br>Frontend flow: <code>pencil → edit → Publish</code>','Troubleshooting'=>['If the toolbar does not appear, confirm visual mode is enabled and the logged-in user has the required admin permission.','If HTML is stripped, the sanitizer intentionally removed dangerous tags, event attributes or unsafe URLs.','If publishing reports a conflict, reload the current revision and reapply only the intended changes.'],'Official'=>[]],
'ai-bedrock'=>['Overview'=>'PocketCat can connect AI features to Amazon Bedrock through an OpenAI-compatible endpoint. The current architecture prefers the Cloudflare Worker relay so provider secrets remain off the browser/PHP public surface. Normal Chat uses Chat Completions and Agent mode uses Responses.','Requirements'=>'Depending on the chosen transport: a PocketCat admin default connection or user credentials, Amazon Bedrock access, a supported model, region, and—when using the relay—the Worker URL and shared relay token.','Steps'=>['Open AWS Bedrock in the AWS console and confirm model access and credentials for your account.','For relay mode, configure the Cloudflare Worker with the Bedrock API secret and relay token.','In PocketCat, open Settings → AWS Bedrock.','Enter the region and model ID if overriding the administrator default.','Use the recommended Cloudflare Worker Relay transport and enter its URL/token when your deployment requires a user-level override.','Save and run Test My Bedrock Connection.'],'Examples'=>'Model ID: <code>openai.gpt-oss-120b</code><br>Base endpoint: <code>https://bedrock-mantle.us-east-1.api.aws/v1</code><br>Relay URL: <code>https://YOUR-WORKER.workers.dev</code><br><strong>Never paste a real secret into documentation or screenshots.</strong>','Troubleshooting'=>['401/403: verify the key/token and AWS permissions.','Model unavailable: verify the selected model is enabled/available in the selected region.','Relay failure: check the Worker health endpoint, configured secret names, region and model variables.','Quota message: check the plan’s daily AI allowance and remember only active processing time is deducted.'],'Official'=>[['AWS Bedrock documentation','https://docs.aws.amazon.com/bedrock/'],['Amazon Bedrock API keys','https://docs.aws.amazon.com/bedrock/latest/APIReference/API_runtime_InvokeModel.html'],['Cloudflare Workers','https://developers.cloudflare.com/workers/']]],
'file-storage'=>['Overview'=>'The file platform stores original/lossless files using an S3-compatible driver, with Cloudflare R2 or AWS S3 as the intended cloud providers. It supports presigned uploads, sharing, previews, limits, expiry, download controls and optional scanning.','Requirements'=>'Admin access, an S3-compatible bucket, endpoint, region, bucket name and access/secret credentials. Public sharing may also require a public base URL or suitable provider configuration.','Steps'=>['Create an S3 bucket or Cloudflare R2 bucket.','Create credentials with only the permissions required by the bucket.','Storage settings are managed internally by the deployment administrator; there is no user-facing Storage Settings page.','Set plan file/storage limits and optional scanner webhook in the deployment configuration.','Save and test with a small file upload before production rollout.'],'Examples'=>'Cloudflare R2 endpoint shape: <code>https://ACCOUNT_ID.r2.cloudflarestorage.com</code><br>Bucket: <code>pocketcat-files</code><br>Public base (optional): <code>https://files.example.com</code>','Troubleshooting'=>['403 on upload: check bucket permissions and credentials.','CORS/preview problems: configure the provider bucket CORS rules for your PocketCat origin.','Large upload problems: confirm multipart/presigned configuration and browser network errors.','Scanner not running: verify the scanner webhook URL and that the scanner can reach the callback endpoint.'],'Official'=>[['Cloudflare R2 docs','https://developers.cloudflare.com/r2/'],['AWS S3 docs','https://docs.aws.amazon.com/s3/']]],
'link-api'=>['Overview'=>'PocketCat’s link engine creates stable short links, tracks analytics and exposes a bearer-token API for link CRUD/analytics workflows. Tokens are displayed only at creation time.','Requirements'=>'A logged-in account for personal API tokens; administrative controls may be required for advanced link policies.','Steps'=>['Open Settings → API Access.','Enter a descriptive token label.','Create the token.','Copy it immediately; PocketCat stores a hash and does not show the full token again.','Send it as an Authorization Bearer token to the link API.','For webhooks, verify the HMAC signature before processing events.'],'Examples'=>'Token shape: <code>pc_live_…</code><br>Header: <code>Authorization: Bearer pc_live_…</code><br>Webhook signature header: <code>X-PocketCat-Signature</code>','Troubleshooting'=>['401: confirm the token was copied correctly and is not revoked.','Webhook rejected: verify the HMAC calculation and raw request body handling.','Analytics mismatch: account for bot filtering, unique-visitor logic and delayed aggregation.'],'Official'=>[]],
'code-editor'=>['Overview'=>'The code editor provides a responsive browser editor, syntax highlighting, previews, version history, export formats and an optional BYOD/E2EE path using personal Firebase storage.','Requirements'=>'Modern browser with Web Crypto support. BYOD requires a Firebase project, appropriate database rules, anonymous authentication if using the current handshake, and a master passphrase that is never stored by PocketCat.','Steps'=>['Open Code and create/open a snippet or workspace.','Choose language and editor options.','Use Visual/Code workspace controls and Preview where applicable.','For BYOD, enter your Firebase project configuration and initialize the connection.','Set a strong master passphrase and keep a recovery record securely.','Test a small encrypted record before using BYOD for important work.'],'Examples'=>'Firebase project ID example: <code>my-pocketcat-project</code><br>Web config fields include <code>apiKey</code>, <code>authDomain</code>, <code>projectId</code>, <code>storageBucket</code>.<br>Never publish a master passphrase.','Troubleshooting'=>['Firebase connection failure: check project ID, database/provider selection, Auth configuration and browser console errors.','Lost master passphrase: encrypted BYOD data cannot be decrypted by PocketCat; recovery depends on your own backup.','Cross-device issues: use the same Firebase configuration and master passphrase.','Preview restrictions: browser sandboxing intentionally limits unsafe execution.'],'Official'=>[['Firebase documentation','https://firebase.google.com/docs/'],['Firebase Console','https://console.firebase.google.com/']]],
'visual-editor'=>['Overview'=>'The Visual Customizer lets an authorized administrator select live page elements, edit them in context, adjust a small style set and publish immutable visual versions with rollback support.','Requirements'=>'Administrator role, visual editor permission and a page opened with visual mode enabled. The backend visual engine API must be reachable and CSRF validation must succeed.','Steps'=>['Open the relevant public page while signed in as an authorized administrator.','Enable visual mode.','Hover an editable element and click its pencil.','Edit the content in place.','Use the style inspector for padding, margin, radius and text shadow.','Publish the revision.','Use the Visual Command Center to inspect versions and roll back if necessary.'],'Examples'=>'URL pattern: <code>/page-slug?visual=1</code><br>Style values: <code>padding: 16px</code>, <code>border-radius: 12px</code>','Troubleshooting'=>['No pencil: verify the visual query flag and admin permission.','Publish conflict: another revision may have been published; reload before publishing again.','Style not visible: confirm the selected element is the intended DOM node and inspect computed styles.'],'Official'=>[]],
'control-plane'=>['Overview'=>'The Super Admin Control Plane centralizes plan policies, feature flags, rate limits, roles, user controls, asset controls and audit records so operational behavior can be changed without redeploying code.','Requirements'=>'Super Admin access. Changes should be made deliberately because global policy flags can affect multiple users.','Steps'=>['Open Admin → Control Plane.','Review the current plan matrix before changing limits.','Change one policy at a time and save.','Use audit history to verify who changed what.','Use kill switches only for incidents or controlled rollout.','Validate the affected feature as Free, Basic and Premium where applicable.'],'Examples'=>'Policy examples include <code>visual_editor</code>, <code>visual_custom_js</code>, <code>visual_runtime</code>, <code>visual_scheduling</code> and BYOD-related policy flags.','Troubleshooting'=>['Feature unexpectedly disabled: check global and plan-level policy flags.','Permission denied: verify role/RBAC assignment.','Unexpected quota: inspect plan limits and per-user overrides.'],'Official'=>[]],
'projects-tasks-notes'=>['Overview'=>'Projects, tasks and notes form the core productivity workspace. Projects organize work; tasks capture actionable items; notes hold reference material.','Requirements'=>'A logged-in account and the relevant project/task/note permissions.','Steps'=>['Open Dashboard.','Create a project when work needs a shared container.','Create tasks for actionable work and notes for reference information.','Edit or delete items through their dedicated routes.','Use search/navigation to return to existing workspace content.'],'Examples'=>'Typical project: <code>Website Launch</code>; task: <code>Configure R2</code>; note: <code>Production deployment checklist</code>.','Troubleshooting'=>['If an item cannot be edited, check login state and ownership/permission rules.','If navigation appears stale, reload after creating/deleting an item.'],'Official'=>[]],
'security-auth'=>['Overview'=>'Authentication and security controls protect user accounts, administrative actions and state-changing requests. PocketCat uses login/roles, CSRF protection and forced password-reset flows where required.','Requirements'=>'A valid account and access to the configured authentication flow. Admin-only features require the correct role/permission.','Steps'=>['Use the normal login page.','For administrative features, confirm the account has the required role.','Complete password reset when a forced reset is required.','Keep API tokens and cloud credentials out of client-side code and screenshots.','Review admin security and audit screens regularly.'],'Examples'=>'CSRF is sent as a hidden form token or, for supported API requests, the <code>X-CSRF-Token</code> header.','Troubleshooting'=>['CSRF error: refresh the page and submit a newly issued form/token.','Forced reset: complete the password reset flow before accessing protected pages.','Permission error: verify role and control-plane permissions.'],'Official'=>[]],
'billing-plans'=>['Overview'=>'PocketCat uses Free, Basic and Premium capability tiers. Limits and feature availability are enforced by the policy/control-plane layer rather than only by frontend UI.','Requirements'=>'A logged-in account for account-level features; billing configuration depends on the deployment.','Steps'=>['Review Pricing/Billing for the plan capabilities.','Choose a plan appropriate for AI, files, code and advanced features.','After a plan change, re-check the feature’s effective policy.','Administrators can inspect plan policies from the Control Plane.'],'Examples'=>'Plan names: <code>free</code>, <code>basic</code>, <code>premium</code>.','Troubleshooting'=>['A UI control may be visible while the server still rejects the action if policy does not allow it.','If a plan change does not appear, refresh and inspect the effective user policy.'],'Official'=>[]],
'media'=>['Overview'=>'The media system provides admin-facing asset upload/archive workflows that can be used by site content and editor features.','Requirements'=>'Admin permissions and a working upload destination.','Steps'=>['Open Admin → Media.','Upload or inspect an asset.','Use the archive/extraction tools where supported.','Insert or reference the resulting asset from editor/media workflows.'],'Examples'=>'An uploaded image should resolve to a PocketCat-managed asset URL rather than a hardcoded WordPress media function.','Troubleshooting'=>['Upload failure: verify storage destination and PHP upload limits.','Broken preview: verify MIME type, file accessibility and storage configuration.'],'Official'=>[]],
];
